class AuthenticationManager {
private:
    int ttl;
    unordered_map<string, int> tokens;
public:
    AuthenticationManager(int timeToLive) : ttl(timeToLive) {}

    void generate(string tokenId, int currentTime) {
        tokens[tokenId] = currentTime + ttl;
    }

    void renew(string tokenId, int currentTime) {
        auto it = tokens.find(tokenId);
        if (it != tokens.end() && it->second > currentTime) {
            it->second = currentTime + ttl;
        }
    }

    int countUnexpiredTokens(int currentTime) {
        int count = 0;
        for (const auto& kv : tokens) {
            if (kv.second > currentTime) count++;
        }
        return count;
    }
};

class AuthenticationManager {
    private int ttl;
    private Map<String, Integer> tokens;

    public AuthenticationManager(int timeToLive) {
        this.ttl = timeToLive;
        this.tokens = new HashMap<>();
    }

    public void generate(String tokenId, int currentTime) {
        tokens.put(tokenId, currentTime + ttl);
    }

    public void renew(String tokenId, int currentTime) {
        Integer exp = tokens.get(tokenId);
        if (exp != null && exp > currentTime) {
            tokens.put(tokenId, currentTime + ttl);
        }
    }

    public int countUnexpiredTokens(int currentTime) {
        int count = 0;
        for (int exp : tokens.values()) {
            if (exp > currentTime) count++;
        }
        return count;
    }
}

class AuthenticationManager {
  constructor(timeToLive) {
    this.ttl = timeToLive;
    this.tokens = new Map();
  }

  generate(tokenId, currentTime) {
    this.tokens.set(tokenId, currentTime + this.ttl);
  }

  renew(tokenId, currentTime) {
    const exp = this.tokens.get(tokenId);
    if (exp !== undefined && exp > currentTime) {
      this.tokens.set(tokenId, currentTime + this.ttl);
    }
  }

  countUnexpiredTokens(currentTime) {
    let count = 0;
    for (const exp of this.tokens.values()) {
      if (exp > currentTime) count++;
    }
    return count;
  }
}
